use xiom.io;
type CalcState = {
  value: Int;
  memory: Int;
  history_count: Int;
}

fn add(state: &mut CalcState, n: Int) -> Int {
  state.value = state.value + n;
  state.history_count += 1;
  state.value
}

fn multiply(state: &mut CalcState, n: Int) -> Int {
  state.value = state.value * n;
  state.history_count += 1;
  state.value
}

fn store_memory(state: &mut CalcState) {
  state.memory = state.value;
}

fn recall_memory(state: &mut CalcState) {
  state.value = state.memory;
}

fn main() -> Int {
  var calc = CalcState{ value: 0, memory: 0, history_count: 0 };
  io.println((add(&mut calc, 10)).to_str());
  io.println((multiply(&mut calc, 3)).to_str());
  store_memory(&mut calc);
  io.println((add(&mut calc, 5)).to_str());
  recall_memory(&mut calc);
  io.println(calc.value.to_str());
  return 0;
}
